.demo__media {
  position: relative;
}

.demo__media--dual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.demo__panel {
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--border);
  box-shadow: 0 24px 64px rgba(0,0,0,0.5);
  background: var(--surface);
}

.demo__panel-logo {
  display: flex;
  align-items: center;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
  background: rgba(255,255,255,0.04);
}

.demo__logo {
  height: 44px;
  width: auto;
  display: block;
}

.demo__logo[alt="ChatGPT"] {
  height: 44px;
}

.demo__logo[alt="Gemini"] {
  height: 36px;
}

.demo__panel-video {
  width: 100%;
  height: auto;
  display: block;
}

.demo__img {
  width: 100%;
  height: auto;
  display: block;
}

.demo__slideshow {
  position: relative;
}

.demo__slide {
  display: none;
  width: 100%;
  height: auto;

