/* ===========================
   RESET & BASE
   =========================== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --purple: #7D3AF2;
  --purple-light: #9B6AF5;
  --purple-dark: #5A28B8;
  --purple-glow: rgba(125, 58, 242, 0.35);
  --bg: #080810;
  --bg-2: #0e0e1a;
  --bg-3: #13131f;
  --card: #141420;
  --border: rgba(255,255,255,0.07);
  --text: #f0f0f8;
  --text-muted: #8888aa;
  --white: #ffffff;
  --font: 'Pretendard', -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', sans-serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  overflow-x: hidden;
}

a { text-decoration: none; color: inherit; }
img { max-width: 100%; display: block; }

/* ===========================
   LAYOUT
   =========================== */
.container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ===========================
   BUTTONS
   =========================== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: none;
  cursor: pointer;
  font-family: var(--font);
  font-weight: 600;
  border-radius: 10px;
  transition: all 0.2s ease;
  text-align: center;
  white-space: nowrap;
}

.btn--primary {
  background: var(--purple);
  color: var(--white);
  box-shadow: 0 0 32px var(--purple-glow);
}
.btn--primary:hover {
  background: var(--purple-light);
  box-shadow: 0 0 48px rgba(123,109,181,0.5);
  transform: translateY(-2px);
}

.btn--ghost {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid var(--border);
}
.btn--ghost:hover {
  color: var(--white);
  border-color: rgba(255,255,255,0.2);
}

.btn--sm  { padding: 10px 20px; font-size: 13px; }
.btn--lg  { padding: 16px 32px; font-size: 16px; }
.btn--xl  { padding: 20px 40px; font-size: 17px; }
.btn--full { width: 100%; }

/* ===========================
   NAV
   =========================== */
.nav {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 100;
  padding: 16px 0;
  border-bottom: 1px solid transparent;
  transition: all 0.3s ease;
}
.nav.scrolled {
  background: rgba(8, 8, 16, 0.92);
  backdrop-filter: blur(16px);
  border-bottom-color: var(--border);
}
.nav__inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.nav__logo img { height: 36px; width: auto; object-fit: contain; }

/* ===========================
   SECTION LABELS
   =========================== */
.section-label {
  display: inline-block;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--purple-light);
  background: rgba(80,63,149,0.12);
  border: 1px solid rgba(80,63,149,0.3);
  padding: 6px 14px;
  border-radius: 100px;
  margin-bottom: 20px;
}

.section-title {
  font-size: clamp(30px, 5vw, 48px);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 48px;
}

.highlight {
  color: var(--purple-light);
}

/* ===========================
   HERO
   =========================== */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: 120px 0 80px;
  position: relative;
  overflow: hidden;
  width: 100%;
}

.hero__bg-img {
  display: none;
}

.hero__bg-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  opacity: 0.3;
  pointer-events: none;
  z-index: 0;
}

/* Hero AI Logos */
.hero__logos {
  position: absolute;
  top: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 48px;
  pointer-events: none;
  z-index: 0;
}

.hero__logos--left {
  left: 40px;
}

.hero__logo-img {
  width: auto;
  max-width: 160px;
  height: auto;
  max-height: 80px;
  object-fit: contain;
  opacity: 0.25;
  filter: grayscale(100%) brightness(2);
}

.hero__bg-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse 80% 80% at 50% 50%, black 30%, transparent 100%);
  pointer-events: none;
}

.hero .container {
  position: relative;
  z-index: 1;
  max-width: 1100px;
  width: 100%;
  margin: 0 auto;
  padding: 0 24px;
}

.hero__badge,
.hero__title,
.hero__sub,
.hero__actions,
.hero__search-demo {
  max-width: 34vw;
}

.hero__badge {
  display: inline-block;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--purple-light);
  background: rgba(80,63,149,0.12);
  border: 1px solid rgba(80,63,149,0.3);
  padding: 8px 16px;
  border-radius: 100px;
  margin-bottom: 28px;
}

.hero__title {
  font-size: clamp(28px, 2.8vw, 44px);
  font-weight: 900;
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 24px;
}

.hero__sub {
  font-size: 18px;
  color: var(--text-muted);
  line-height: 1.7;
  margin-bottom: 40px;
  max-width: 560px;
}

.hero__actions {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 64px;
}

/* Search Demo */
.hero__search-demo {
  max-width: 560px;
}

.search-demo {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
}

.search-demo__bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
}

.search-demo__icon {
  color: var(--purple-light);
  font-size: 16px;
}

.search-demo__text {
  font-size: 14px;
  color: var(--text);
  flex: 1;
}

.search-demo__cursor {
  color: var(--purple-light);
  animation: blink 1s step-end infinite;
}

@keyframes blink {
  50% { opacity: 0; }
}

.search-demo__result {
  padding: 16px 20px;
  opacity: 0;
  transform: translateY(8px);
  transition: all 0.4s ease;
}

.search-demo__result.visible {
  opacity: 1;
  transform: translateY(0);
}

.result-card {
  background: rgba(80,63,149,0.08);
  border: 1px solid rgba(80,63,149,0.25);
  border-radius: 10px;
  padding: 14px 16px;
}

.result-card__rank {
  font-size: 11px;
  font-weight: 700;
  color: var(--purple-light);
  letter-spacing: 0.1em;
  margin-bottom: 6px;
}

.result-card__name {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 4px;
}

.result-card__desc {
  font-size: 13px;
  color: var(--text-muted);
}

/* ===========================
   PROBLEM
   =========================== */
.problem {
  padding: 120px 0;
  background: var(--bg-2);
}

/* ── 비교 레이아웃 ── */
.compare {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 0;
  align-items: stretch;
  margin-bottom: 72px;
}

.compare__col {
  padding: 36px;
  border-radius: 20px;
  border: 1px solid var(--border);
  background: var(--card);
}

.compare__col--new {
  border-color: rgba(80,63,149,0.4);
  background: rgba(80,63,149,0.05);
}

.compare__label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.compare__label--new {
  color: var(--purple-light);
}

.compare__platform {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 20px;
}

.compare__platform-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--text-muted);
  flex-shrink: 0;
}

.compare__platform-dot--new {
  background: var(--purple-light);
  box-shadow: 0 0 8px var(--purple-light);
}

/* 포털 검색 모형 */
.compare__mockup {
  border-radius: 12px;
  overflow: hidden;
  margin-bottom: 24px;
  border: 1px solid var(--border);
}

.compare__mockup--portal {
  background: #1a1a2a;
}

.portal-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: #101020;
  border-bottom: 1px solid var(--border);
  font-size: 13px;
  color: var(--text-muted);
}

.portal-icon { font-size: 14px; }

.portal-results {
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.portal-result {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: #13131e;
  border-radius: 8px;
  border: 1px solid var(--border);
}

.portal-result--organic {
  opacity: 0.5;
}

.portal-result__ad {
  font-size: 10px;
  font-weight: 700;
  color: #e8c355;
  background: rgba(232,195,85,0.1);
  border: 1px solid rgba(232,195,85,0.2);
  padding: 2px 5px;
  border-radius: 3px;
  flex-shrink: 0;
}

.portal-result__title {
  font-size: 12px;
  color: var(--text-muted);
}

/* AI 검색 모형 */
.compare__mockup--ai {
  background: #0e0e1a;
  padding: 16px;
}

.ai-query {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 14px;
}

.ai-query__icon {
  color: var(--purple-light);
  font-size: 16px;
  flex-shrink: 0;
  margin-top: 2px;
}

.ai-query__text {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.5;
  font-style: italic;
}

.ai-answer {
  background: rgba(80,63,149,0.08);
  border: 1px solid rgba(80,63,149,0.25);
  border-radius: 10px;
  padding: 14px;
}

.ai-answer__header {
  font-size: 11px;
  font-weight: 700;
  color: var(--purple-light);
  letter-spacing: 0.08em;
  margin-bottom: 10px;
}

.ai-answer__item {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ai-answer__rank {
  width: 26px;
  height: 26px;
  background: var(--purple);
  color: white;
  font-size: 13px;
  font-weight: 800;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ai-answer__name {
  font-size: 14px;
  font-weight: 700;
}

.ai-answer__reason {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
}

/* 포인트 리스트 */
.compare__points {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.compare__point {
  font-size: 13px;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 8px;
  line-height: 1.4;
}

.compare__point::before {
  content: '✕';
  font-size: 11px;
  font-weight: 700;
  color: #e05555;
  flex-shrink: 0;
}

.compare__point--good::before {
  content: '✓';
  color: var(--purple-light);
}

/* 가운데 구분선 */
.compare__divider {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 0 24px;
  gap: 12px;
  min-height: 300px;
}

.compare__divider-line {
  flex: 1;
  width: 1px;
  background: var(--border);
}

.compare__divider-badge {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 100px;
  padding: 6px 12px;
}

/* ── 통계 ── */
.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: var(--border);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  margin-bottom: 0;
}

.stat {
  background: var(--card);
  padding: 36px 32px;
  text-align: center;
}

.stat__num {
  font-size: 48px;
  font-weight: 900;
  letter-spacing: -0.03em;
  color: var(--purple-light);
  line-height: 1;
  margin-bottom: 10px;
}

.stat__label {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.5;
}

/* ===========================
   NEWS CARDS
   =========================== */
.news-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 16px;
  margin-top: 0;
}

.news-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 56px;
}

.news-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 22px;
  transition: border-color 0.2s ease, transform 0.2s ease;
  text-decoration: none;
  color: inherit;
  cursor: pointer;
  display: block;
}

.news-card:hover {
  border-color: rgba(80,63,149,0.35);
  transform: translateY(-3px);
}

.news-card__source {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
}

.news-card__badge {
  font-size: 11px;
  font-weight: 700;
  color: var(--purple-light);
  background: rgba(80,63,149,0.12);
  border: 1px solid rgba(80,63,149,0.25);
  padding: 3px 8px;
  border-radius: 4px;
}

.news-card__date {
  font-size: 11px;
  color: var(--text-muted);
}

.news-card__title {
  font-size: 15px;
  font-weight: 700;
  line-height: 1.5;
  margin-bottom: 10px;
  color: var(--white);
}

.news-card__desc {
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.7;
}

/* ===========================
   SOLUTION
   =========================== */
.solution {
  padding: 120px 0;
  overflow: hidden;
  position: relative;
}

.solution::before {
  content: '';
  position: absolute;
  inset: 0;
  background: url('images/hero-main.jpg') center center / 90% auto no-repeat;
  opacity: 0.18;
  mask-image:
    linear-gradient(to right, transparent 0%, black 20%, black 80%, transparent 100%),
    linear-gradient(to bottom, transparent 0%, black 20%, black 80%, transparent 100%);
  mask-composite: intersect;
  -webkit-mask-image:
    linear-gradient(to right, transparent 0%, black 20%, black 80%, transparent 100%),
    linear-gradient(to bottom, transparent 0%, black 20%, black 80%, transparent 100%);
  -webkit-mask-composite: source-in;
  pointer-events: none;
  z-index: 0;
}

.solution__layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 72px;
  align-items: center;
  position: relative;
  z-index: 1;
}

.solution__text {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  min-width: 0;
}

.solution__3d-wrap {
  display: none;
}

.solution__img-wrap {
  min-width: 0;
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid var(--border);
  box-shadow: 0 24px 64px rgba(0,0,0,0.5);
}

.solution__img {
  width: 100%;
  height: auto;
  display: block;
}

/* 3D 이미지 */
.solution__3d-wrap {
  perspective: 1200px;
  display: flex;
  justify-content: center;
  width: 100%;
}

.solution__3d-img {
  width: 100%;
  max-width: 540px;
  height: auto;
  display: block;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.08);
  transform: perspective(1200px) rotateY(-18deg) rotateX(4deg) scale(1.02);
  box-shadow:
    -24px 24px 64px rgba(0,0,0,0.6),
    0 0 0 1px rgba(80,63,149,0.15),
    inset 0 1px 0 rgba(255,255,255,0.06);
  transition: transform 0.5s ease, box-shadow 0.5s ease;
}

.solution__3d-wrap:hover .solution__3d-img {
  transform: perspective(1200px) rotateY(-8deg) rotateX(2deg) scale(1.04);
  box-shadow:
    -32px 32px 80px rgba(0,0,0,0.7),
    0 0 0 1px rgba(80,63,149,0.3),
    inset 0 1px 0 rgba(255,255,255,0.08);
}

.solution__desc {
  font-size: 16px;
  color: var(--text-muted);
  line-height: 1.8;
  margin-bottom: 20px;
  align-self: stretch;
}

.solution__desc strong { color: var(--white); }

.solution__list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-top: 8px;
  align-self: stretch;
}

.solution__list li {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 15px;
  color: var(--text-muted);
}

.check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  background: rgba(80,63,149,0.15);
  border: 1px solid rgba(80,63,149,0.4);
  border-radius: 6px;
  color: var(--purple-light);
  font-size: 12px;
  flex-shrink: 0;
}

/* Card Carousel */
.card-carousel {
  width: 100%;
  max-width: 100%;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.card-carousel__track-wrap {
  overflow: hidden;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.08);
  cursor: grab;
  user-select: none;
  transform: perspective(1200px) rotateY(-18deg) rotateX(4deg) scale(1.02);
  box-shadow:
    -24px 24px 64px rgba(0,0,0,0.6),
    0 0 0 1px rgba(80,63,149,0.15),
    inset 0 1px 0 rgba(255,255,255,0.06);
  transition: transform 0.5s ease, box-shadow 0.5s ease;
}

.solution__3d-wrap:hover .card-carousel__track-wrap {
  transform: perspective(1200px) rotateY(-8deg) rotateX(2deg) scale(1.04);
  box-shadow:
    -32px 32px 80px rgba(0,0,0,0.7),
    0 0 0 1px rgba(80,63,149,0.3),
    inset 0 1px 0 rgba(255,255,255,0.08);
}

.card-carousel__track {
  display: flex;
  gap: 0;
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.card-carousel__item {
  flex-shrink: 0;
  overflow: hidden;
  border-radius: 0;
  background: #fff;
}

.card-carousel__item img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: contain;
  background: #fff;
}

.card-carousel__controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
}

.card-carousel__btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--card);
  color: var(--text);
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.2s ease, background 0.2s ease;
  flex-shrink: 0;
}

.card-carousel__btn:hover {
  border-color: var(--purple);
  background: rgba(80,63,149,0.15);
  color: var(--white);
}

.card-carousel__dots {
  display: flex;
  gap: 8px;
  align-items: center;
}

.card-carousel__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--border);
  transition: background 0.2s ease, width 0.2s ease;
  cursor: pointer;
}

.card-carousel__dot--active {
  background: var(--purple-light);
  width: 20px;
  border-radius: 3px;
}

/* Section header center alignment */
.problem .container > .section-label,
.demo .container > .section-label,
.how .container > .section-label {
  display: table;
  margin: 0 auto 20px;
}

/* solution 섹션: section-title 전체 너비 사용 */
.solution__text > .section-title {
  align-self: stretch;
}

.problem .container > .section-title,
.demo .container > .section-title,
.how .container > .section-title {
  text-align: center;
}

/* Demo Video Section */
.demo {
  padding: 120px 0;
  background: var(--bg);
}

.demo__desc {
  font-size: 16px;
  color: var(--text-muted);
  margin-bottom: 48px;
  max-width: 700px;
  text-align: center;
  margin-left: auto;
  margin-right: auto;
  word-break: keep-all;
  white-space: normal;
}

.demo__media {
  position: relative;
}

.demo__media--dual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.demo__panel {
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--border);
  box-shadow: 0 24px 64px rgba(0,0,0,0.5);
  background: var(--surface);
  position: relative;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
}

.demo__panel:hover {
  transform: translateY(-4px);
  box-shadow: 0 32px 80px rgba(0,0,0,0.6);
}

.demo__panel-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,0);
  transition: background 0.2s;
  z-index: 2;
}

.demo__panel:hover .demo__panel-overlay {
  background: rgba(0,0,0,0.35);
}

.demo__play-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  backdrop-filter: blur(8px);
  border: 2px solid rgba(255,255,255,0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  color: #fff;
  opacity: 0;
  transform: scale(0.8);
  transition: opacity 0.2s, transform 0.2s;
  pointer-events: none;
  line-height: 1;
  padding-left: 4px;
}

.demo__panel:hover .demo__play-icon {
  opacity: 1;
  transform: scale(1);
}

/* 동영상 모달 */
.video-modal {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 9000;
  align-items: center;
  justify-content: center;
}

.video-modal.is-open {
  display: flex;
}

.video-modal__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.85);
  backdrop-filter: blur(6px);
  cursor: pointer;
}

.video-modal__content {
  position: relative;
  z-index: 1;
  width: 90vw;
  max-width: 1100px;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 40px 120px rgba(0,0,0,0.8);
  animation: modalIn 0.25s ease;
}

@keyframes modalIn {
  from { opacity: 0; transform: scale(0.93); }
  to   { opacity: 1; transform: scale(1); }
}

.video-modal__close {
  position: absolute;
  top: 14px;
  right: 14px;
  z-index: 2;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  color: #fff;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}

.video-modal__close:hover {
  background: rgba(255,255,255,0.15);
}

.video-modal__video {
  width: 100%;
  height: auto;
  display: block;
}

.demo__panel-logo {
  display: flex;
  align-items: center;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
  background: rgba(255,255,255,0.04);
}

.demo__logo {
  height: 44px;
  width: auto;
  display: block;
}

.demo__logo[alt="ChatGPT"] {
  height: 44px;
}

.demo__logo[alt="Gemini"] {
  height: 36px;
}

.demo__panel-video {
  width: 100%;
  height: auto;
  display: block;
}

.demo__img {
  width: 100%;
  height: auto;
  display: block;
}

.demo__slideshow {
  position: relative;
}

.demo__slide {
  display: none;
  width: 100%;
  height: auto;
}

.demo__slide--active {
  display: block;
}

/* Demo Screen */
.demo-screen {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
}

.demo-screen__header {
  padding: 12px 16px;
  background: var(--bg-3);
  border-bottom: 1px solid var(--border);
  display: flex;
  gap: 8px;
}

.demo-screen__header span {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--border);
}

.demo-img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: contain;
}

/* ===========================
   PROOF
   =========================== */
.proof {
  padding: 120px 0;
  background: var(--bg);
}

.proof__header {
  display: grid;
  grid-template-columns: 5fr 4fr;
  gap: 32px;
  margin-bottom: 20px;
}

.proof__header .news-label {
  margin: 0;
}

.proof__row {
  display: grid;
  grid-template-columns: 5fr 4fr;
  gap: 32px;
  align-items: stretch;
}

.proof__news {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.proof__news .news-card {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.proof__news .news-card__desc {
  flex: 1;
}

.proof__images {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.proof__images-label {
  margin-top: 0;
  margin-bottom: 0 !important;
}

.proof__images-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  align-items: stretch;
  flex: 1;
}

.proof__images .how__img-wrap {
  border-radius: 14px;
  border: 1px solid var(--border);
  overflow: hidden;
  background: #ffffff;
  height: 100%;
}

.proof__images .how__img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
}

/* ===========================
   HOW IT WORKS
   =========================== */
.how {
  padding: 120px 0;
  background: var(--bg-2);
}

.how__steps {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-bottom: 0;
  position: relative;
}

.how__steps::before {
  content: '';
  position: absolute;
  left: 28px;
  top: 0;
  bottom: 0;
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--purple), transparent);
}

.how__step {
  display: flex;
  gap: 32px;
  align-items: flex-start;
  padding: 32px 0;
  border-bottom: 1px solid var(--border);
}

.how__step:last-child { border-bottom: none; }

.how__step-num {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--purple-light);
  background: rgba(80,63,149,0.12);
  border: 1px solid rgba(80,63,149,0.3);
  width: 56px;
  height: 56px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  position: relative;
  z-index: 1;
}

.how__step-content h3 {
  font-size: 24px;
  font-weight: 700;
  margin-bottom: 8px;
}

.how__step-content p {
  font-size: 15px;
  color: var(--text-muted);
  line-height: 1.7;
}

.how__images {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  align-items: stretch;
  max-width: 100%;
  margin: 0 auto;
}

.how__img-wrap {
  border-radius: 14px;
  border: 1px solid var(--border);
  overflow: hidden;
  display: flex;
  align-items: flex-start;
  background: #ffffff;
}

.how__img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: contain;
  object-position: top;
}

/* ===========================
   URGENCY
   =========================== */
.urgency {
  padding: 120px 0;
  background: linear-gradient(135deg, rgba(80,63,149,0.08) 0%, transparent 60%);
}

.urgency__inner {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.urgency__icon {
  font-size: 40px;
  margin-bottom: 24px;
  display: block;
}

.urgency__title {
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 900;
  letter-spacing: -0.02em;
  margin-bottom: 48px;
}

.urgency__points {
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-bottom: 48px;
  text-align: left;
}

.urgency__point {
  display: flex;
  gap: 20px;
  align-items: flex-start;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 24px;
}

.urgency__point-num {
  font-size: 28px;
  font-weight: 900;
  color: var(--purple-light);
  line-height: 1;
  flex-shrink: 0;
  opacity: 0.4;
}

.urgency__point p {
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-muted);
}

.urgency__point p strong { color: var(--white); }

.urgency__cta-text {
  font-size: 16px;
  color: var(--text-muted);
  margin-bottom: 32px;
}

/* ===========================
   APPLY FORM
   =========================== */
.apply {
  padding: 120px 0;
  background: var(--bg-2);
  text-align: center;
}

.apply__sub {
  font-size: 16px;
  color: var(--text-muted);
  margin-bottom: 56px;
  margin-top: -24px;
  line-height: 1.7;
}

.apply-form {
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
  text-align: left;
}

#submitBtn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.form-group label {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.form-group input,
.form-group textarea {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px;
  font-family: var(--font);
  font-size: 15px;
  color: var(--white);
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  resize: vertical;
}

.form-group input::placeholder,
.form-group textarea::placeholder {
  color: #555570;
}

.form-group input:focus,
.form-group textarea:focus {
  border-color: var(--purple);
  box-shadow: 0 0 0 3px var(--purple-glow);
}

.form-group input.error,
.form-group textarea.error {
  border-color: #e05555;
}

.form-error {
  font-size: 12px;
  color: #e05555;
  min-height: 0;
  display: none;
}

.form-error:not(:empty) {
  display: block;
}

.required { color: var(--purple-light); }
.optional { font-size: 12px; color: var(--text-muted); font-weight: 400; }

/* Radio / Checkbox */
.checkbox-group {
  display: flex;
  gap: 16px;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  font-size: 15px;
  color: var(--text-muted);
  user-select: none;
}

.radio-label input[type="radio"],
.radio-label input[type="checkbox"] {
  display: none;
}

.radio-box {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--border);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
}

.radio-box--check {
  border-radius: 6px;
}

.radio-label input[type="radio"]:checked ~ .radio-box {
  border-color: var(--purple);
  background: var(--purple);
  box-shadow: 0 0 0 3px var(--purple-glow);
}

.radio-label input[type="radio"]:checked ~ .radio-box::after {
  content: '';
  width: 8px;
  height: 8px;
  background: white;
  border-radius: 50%;
}

.radio-label input[type="checkbox"]:checked ~ .radio-box--check {
  border-color: var(--purple);
  background: var(--purple);
}

.radio-label input[type="checkbox"]:checked ~ .radio-box--check::after {
  content: '✓';
  color: white;
  font-size: 12px;
  font-weight: 700;
}

.form-privacy {
  border-top: 1px solid var(--border);
  padding-top: 20px;
}

/* Success */
.apply-success {
  text-align: center;
  max-width: 480px;
  margin: 0 auto;
  padding: 64px 40px;
  background: var(--card);
  border: 1px solid rgba(80,63,149,0.3);
  border-radius: 20px;
}

.apply-success__icon {
  font-size: 48px;
  color: var(--purple-light);
  background: rgba(80,63,149,0.1);
  width: 80px;
  height: 80px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
}

.apply-success h3 {
  font-size: 24px;
  font-weight: 800;
  margin-bottom: 12px;
}

.apply-success p {
  color: var(--text-muted);
  line-height: 1.7;
}

/* ===========================
   FOOTER
   =========================== */
.footer {
  padding: 60px 0 40px;
  border-top: 1px solid var(--border);
}

.footer__inner {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 40px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}

.footer__logo { height: 32px; width: auto; margin-bottom: 12px; }

.footer__tagline {
  font-size: 13px;
  color: var(--text-muted);
}

.footer__info {
  font-size: 14px;
  color: var(--text-muted);
  line-height: 2;
}

.footer__info a { color: var(--purple-light); }
.footer__info a:hover { text-decoration: underline; }

.footer__bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.footer__privacy {
  font-size: 12px;
  color: #55556a;
  line-height: 1.6;
  max-width: 600px;
}

.footer__bottom p:last-child {
  font-size: 13px;
  color: #55556a;
  flex-shrink: 0;
}

/* ===========================
   RESPONSIVE
   =========================== */
@media (max-width: 768px) {
  .solution__layout {
    grid-template-columns: 1fr;
  }

  .solution__3d-img {
    transform: none;
  }

  /* Solution 배경 이미지 모바일 투명도 축소 */
  .solution::before {
    opacity: 0.07;
  }

  .compare {
    grid-template-columns: 1fr;
  }

  .compare__divider {
    flex-direction: row;
    min-height: auto;
    padding: 16px 0;
  }

  .compare__divider-line {
    width: auto;
    height: 1px;
    flex: 1;
  }

  .stats-row {
    grid-template-columns: 1fr;
  }

  .news-cards {
    grid-template-columns: 1fr;
  }

  .proof__grid {
    grid-template-columns: 1fr;
  }

  .proof__row {
    grid-template-columns: 1fr;
  }

  .proof__images {
    display: block;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .how__steps::before { display: none; }

  .footer__inner { flex-direction: column; gap: 24px; }

  .footer__bottom { flex-direction: column; align-items: flex-start; }

  /* Hero 모바일 — 전체 너비 사용 */
  .hero__badge,
  .hero__title,
  .hero__sub,
  .hero__actions,
  .hero__search-demo {
    max-width: 100%;
  }

  .hero__badge {
    font-size: 11px;
    padding: 6px 12px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 90vw;
  }

  .hero__title {
    font-size: clamp(28px, 8vw, 40px);
  }

  .hero__actions { flex-direction: column; }
  .hero__actions .btn { width: 100%; justify-content: center; }

  /* Urgency 텍스트 단어 단위 줄바꿈 */
  .urgency__point p {
    word-break: keep-all;
    overflow-wrap: break-word;
  }

  /* Demo 패널 모바일 세로 스택 */
  .demo__media--dual {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .flow { gap: 16px; }
  .flow__step { padding: 24px 28px; }
  .flow__arrow { transform: rotate(90deg); }
}

